INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101542, 'spa', 'paloma (término cariñoso) — Término figurado de cariño dirigido a la amada, rest', 'paloma (término cariñoso) — Término figurado de cariño dirigido a la amada, restringido al Cantar de los Cantares con el sufijo posesivo ''paloma mía'' (Cnt 2:14; 5:2; 6:9). El registro íntimo se confirma en múltiples idiomas: español ''paloma mía'', francés ''ma colombe'', alemán ''meine Taube'', todos marcando el paso de sustantivo zoológico a apelativo afectuoso dentro de la poesía amorosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101552, 'spa', 'Jonas (nombre propio) — El nombre propio Yonah (''paloma''), que designa al profet', 'Jonas (nombre propio) — El nombre propio Yonah (''paloma''), que designa al profeta Jonas hijo de Amitai de Gat-hefer. Las diecinueve apariciones se refieren a este unico individuo, apareciendo en 2 Reyes 14:25 como profeta historico y a lo largo del Libro de Jonas (1:1-4:9) como el misionero renuente a Ninive. El significado del nombre — ''paloma'' — resuena con los temas de huida y retorno que impregnan la narrativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101557, 'spa', 'Brote, retoño', 'Brote tierno, vástago o rama joven que crece de un árbol, vid o planta, siempre con sufijos posesivos que indican la planta de origen. Se usa literalmente del crecimiento botánico (Job 14:7, donde la esperanza reside en la capacidad del árbol de rebrotar) y figuradamente de personas o naciones: la prosperidad engañosa de los impíos (Job 8:16; 15:30), Israel como olivo que extiende sus renuevos (Hos 14:7) y un vástago mesiánico del cedro (Ezek 17:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101562, 'spa', 'Jonatán (nombre propio) — Nombre teofórico que significa ''YHWH ha dado'', aplicad', 'Jonatán (nombre propio) — Nombre teofórico que significa ''YHWH ha dado'', aplicado principalmente al hijo de Saúl, cuya amistad pactada con David (1 S 18:1-4) y muerte en Gilboa (1 S 31:2) son paradigmáticas. También designa al hijo de Abiatar (2 S 15:27), al sobrino de David (2 S 21:21) y al levita de Jueces 18:30.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101568, 'spa', 'Jose (nombre propio)', 'El nombre propio Jose (Yosef / Yehoseph), que significa ''el anade'' o ''que el anade'', referido primariamente al patriarca Jose hijo de Jacob y Raquel (Gn 30:24), cuya narrativa de exilio, sufrimiento y exaltacion providencial abarca Genesis 37-50. Usado metonimicamente para el territorio tribal conjunto de Efrain y Manases (Dt 33:13; Sal 80:2; Ez 37:16). La doble etimologia de Genesis 30:23-24 conecta ''quitar'' y ''anadir'' en un solo nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101580, 'spa', 'Sacerdote exiliado', 'Nombre propio del sacerdote exiliado cuyo hijo Josué llegó a ser sumo sacerdote de la restauración, presentado en la forma contraída Josadac (יוֹצָדָק). El nombre ancla la genealogía sacerdotal en Esd 3:2, 8 (reconstrucción del templo), Esd 10:18 (crisis de los matrimonios mixtos) y Neh 12:26 (registro sacerdotal).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101583, 'spa', 'Lluvia temprana', 'Las lluvias estacionales tempranas, esenciales para una agricultura exitosa en el Levante. Mencionadas en bendiciones del pacto (Deuteronomio) y textos proféticos que emplean el ciclo de lluvias como metáfora de la provisión o el juicio divino. Las traducciones interlingüísticas captan el aspecto temporal que distingue esta lluvia del resto del vocabulario pluvial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101586, 'spa', 'Joram / Yoram (nombre propio) — El nombre propio Joram/Jehoram (יְהוֹרָם / יוֹרָ', 'Joram / Yoram (nombre propio) — El nombre propio Joram/Jehoram (יְהוֹרָם / יוֹרָם / יֹרָם), que significa ''YHWH es exaltado,'' llevado por multiples individuos incluyendo dos reyes casi contemporaneos (de Israel y Juda respectivamente), un sacerdote levita y un principe hamateo. La intercambiabilidad de las formas completa y abreviada dentro de la misma narrativa refleja convenciones escribales flexibles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101596, 'spa', 'Nombre propio masculino Yotam (יוֹתָם), que significa «YHWH es perfecto/íntegro»', 'Nombre propio masculino Yotam (יוֹתָם), que significa «YHWH es perfecto/íntegro», designando a tres individuos. El más memorable es Jotam hijo de Gedeón, quien escapó del fratricidio de Abimelec y pronunció su parábola de la zarza-rey desde el monte Gerizim (Jue 9:5-21, 57). Jotam rey de Judá sirvió primero como regente durante la cuarentena de su leproso padre Uzías y luego como gobernante único (2 Re 15:5, 32-38; 2 Cr 26-27). Su nombre ancla las sobreescrituras de Isaías, Oseas y Miqueas. Un personaje menor calebita también lleva el nombre (1 Cr 2:47).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101600, 'spa', 'Más, en exceso', 'Uso adverbial y comparativo que significa ''más'', ''en gran manera'' o ''en exceso''. En Eclesiastés 7:16 Qohélet advierte contra ser justo ''en demasía'' (אַל־תְּהִי צַדִּיק הַרְבֵּה וְאַל־תִּתְחַכַּם יוֹתֵר), y en 2:15 observa que fue sabio ''excesivamente'' sin provecho alguno. En Ester 6:6 funciona como comparativo intensificador, reforzando la presunción desmedida de Amán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101601, 'spa', 'Además, ventaja', 'Uso conjuntivo-nominal que significa ''además'', ''aparte de eso'' o ''la ventaja/el provecho es''. En Eclesiastés 12:9 abre con וְיֹתֵר שֶׁ (''y además de que''), introduciendo información suplementaria sobre la actividad del Predicador. En 12:12 adquiere un matiz de advertencia: ''y más allá de esto, hijo mío, sé advertido'', donde la palabra pivota de la enumeración a la exhortación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101611, 'spa', 'Nombre teofórico', 'Nombre propio teofórico que invoca el surgir o resplandecer de Yahvé. Su uso dual para un personaje genealógico y un músico levítico refleja la práctica común de reutilizar nombres a través de generaciones y tribus. La forma española «Jezraías» y variantes similares muestran las adaptaciones fonológicas necesarias al traducir nombres hebreos a otras lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101612, 'spa', 'Jezreel (topónimo) — Jezreel como nombre de lugar, principalmente la prominente ', 'Jezreel (topónimo) — Jezreel como nombre de lugar, principalmente la prominente ciudad en el territorio de Isacar al borde del gran valle (Jos 19:18; 1 R 18:45-46), escenario del asesinato judicial de Nabot y la revuelta de Jehú, y secundariamente un pueblo en el Néguev de Judá (Jos 15:56). El nombre del valle se deriva del mismo topónimo que designa toda la llanura fértil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101619, 'spa', 'Jezreel (nombre personal) — Jezreel como nombre propio, llevado por un hijo de E', 'Jezreel (nombre personal) — Jezreel como nombre propio, llevado por un hijo de Etam en la genealogía de Judá (1 Cr 4:3) y por el primogénito de Oseas (Os 1:4), donde la etimología ''Dios siembra'' se activa como juego de palabras profético: primero como juicio por la sangre derramada en la ciudad de Jezreel, y luego invertido en Os 2:22 como promesa de restauración agrícola y nacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101622, 'spa', 'El jezreelita', 'Adjetivo gentilicio que designa a una persona procedente de la ciudad de Jezreel. En su forma masculina (הַיִּזְרְעֵאלִי) identifica a Nabot, cuya viña codició Acab y cuya muerte maquinó Jezabel (1 Re 21:1, 4, 6, 7, 15, 16; 2 Re 9:21, 25). La forma femenina (הַיִּזְרְעֵאלִית) identifica a Ahinoam, esposa de David procedente de Jezreel (1 Sam 27:3; 30:5; 2 Sam 2:2; 3:2; 1 Cr 3:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101624, 'spa', 'Gentilicio femenino', 'Adjetivo gentilicio en forma femenina que identifica a una mujer como originaria de Jezreel, en el territorio de Isacar. En las cinco ocurrencias modifica a Ahinoam, esposa de David, distinguiéndola de otras mujeres homónimas (cf. la esposa de Saúl, Ahinoam). La ortografía alterna entre la terminación larga -ית (1 Sam 30:5; 2 Sam 2:2; 1 Cr 3:1) y la más breve (1 Sam 27:3; 2 Sam 3:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101626, 'spa', 'Unir, concentrar', 'El acto de unir o vincular, ya sea literalmente (ser sepultado junto a otros) o metafóricamente (concentrar los afectos interiores). En el Salmo 86:11, la imagen sugiere un corazón disperso o dividido que es reunido en un propósito unificado, una poderosa representación de integridad espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101628, 'spa', 'juntos, juntamente, a una — Adverbio derivado del sustantivo yachad (''unidad''), ', 'juntos, juntamente, a una — Adverbio derivado del sustantivo yachad (''unidad''), que expresa acción conjunta (Job 38:7, ''las estrellas del alba cantaban juntas''), lugar compartido (Dt 33:5), o cualidad común (Sal 14:3, ''todos a una se han corrompido''). El cognado árabe wahdun significa ''solo'', una inversión semántica instructiva que resalta el énfasis colectivo del hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101632, 'spa', 'Juntos — adverbio que expresa acción conjunta, ubicación compartida o simultanei', 'Juntos — adverbio que expresa acción conjunta, ubicación compartida o simultaneidad: ''juntos, como uno solo, juntamente.'' Abarca actividades comunales como caminar juntos (Gn 22:6, 8), habitar juntos (Gn 13:6; Dt 25:5) y adorar juntos (Sal 34:4). El repetido ''y los dos fueron juntos'' en la Aqedá de Génesis 22 ejemplifica su poder narrativo para expresar compañía silenciosa ante lo inefable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101637, 'spa', 'Jahaziel (nombre propio)', 'Nombre personal Yaḥăzîʾēl (יַחֲזִיאֵל, ''Dios ve/contempla''), llevado por cinco o más hombres: un guerrero benjaminita que se unió a David en Siclag (1 Chr 12:5), un sacerdote que tocaba trompetas ante el arca (1 Chr 16:6), un levita descendiente de Hebrón (1 Chr 23:19; 24:23), el levita profético que anunció la victoria divina para Josafat (2 Chr 20:14), y un ancestro de clan en el retorno del exilio (Ezra 8:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101640, 'spa', 'Nombre teofórico', 'Nombre teofórico que afirma el poder fortalecedor de Dios, asociado principalmente con el profeta de visiones extraordinarias y profecías dramatizadas durante la hora más oscura de Israel. Su aparición tanto para el profeta exílico como para una división sacerdotal anterior muestra que era un nombre establecido que transmitía confianza en la fortaleza divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101643, 'spa', 'Jehiel (nombre propio)', 'Nombre propio masculino (יְחִיאֵל) que significa ''que Dios viva'', transcrito en la Septuaginta como Ιειηλ y Ιαιηλ. Designa al menos a ocho individuos distintos: el músico de David en la procesión del arca (1 Cr 15:18), un jefe levítico sobre los tesoros (1 Cr 23:8; 29:8), un tutor real (1 Cr 27:32), un hijo de Josafat (2 Cr 21:2), funcionarios del templo bajo Ezequías y Josías, y contemporáneos de Esdras y Nehemías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101648, 'spa', 'Único (hijo), unigénito', 'Un hijo único, enfatizando singularidad e irremplazabilidad. El árabe wahid y el arameo yechidai convergen en este significado. Génesis 22:2 carga la palabra con un patetismo devastador: ''tu hijo, tu único''. Jueces 11:34 hace eco con la hija de Jefté: ''era su única hija''. Proverbios 4:3 recuerda una infancia tierna como ''el único ante mi madre''. El sentido no es mera singularidad, sino un vínculo afectivo irremplazable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101649, 'spa', 'Vida preciosa (metafórico)', 'Epíteto poético para la propia vida o alma, ''mi única'' (יְחִידָתִי), usado en paralelo con נַפְשִׁי (''mi alma''). El Salmo 22:20 clama ''libra mi vida preciosa de la espada'' y el Salmo 35:17 suplica ''rescata mi única de los leones''. La forma femenina marca este uso metafórico distintivo: el ser como lo único que no puede reemplazarse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101652, 'spa', 'Solitario, desamparado', 'Solitario, aislado, describiendo a una persona sin compañía ni apoyo. El Salmo 25:16 confiesa ''estoy solo y afligido'', mientras que el Salmo 68:6 celebra a Dios como quien ''da hogar a los solitarios''. El desplazamiento semántico va de la unicidad al aislamiento social: de ser el único a estar solo, del valor singular a la vulnerabilidad del desamparo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101659, 'spa', 'esperar con esperanza — El significado principal en todas las conjugaciones', 'esperar con esperanza — El significado principal en todas las conjugaciones: poner la esperanza o expectativa en alguien, especialmente en Dios, o aguardar con anticipación confiada. En los Salmos es la postura dominante de fe (Sal 31:24; 33:22; 38:15; 130:5-7). Génesis 8:12 muestra el extremo más concreto de ''aguardar''. El matiz causativo del Hifil aparece cuando Dios infunde esperanza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101670, 'spa', 'hacer esperar (causativo) — Uso causativo en Hifil en el Salmo 119', 'hacer esperar (causativo) — Uso causativo en Hifil en el Salmo 119:49 donde el salmista se dirige a Dios: ''Tú me hiciste esperar''. La evidencia multilingüe (''me hiciste esperar'', ''espérer'', ''hoffte'') confirma la fuerza causativa: Dios infundiendo activamente la esperanza en lugar de generarla el hablante. Este sentido subraya la realidad teológica de que la esperanza misma es un don divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101680, 'spa', 'dolerse, retorcerse (uso debatido) — Una ocurrencia debatida en Jeremías 4', 'dolerse, retorcerse (uso debatido) — Una ocurrencia debatida en Jeremías 4:19 donde se traduce ''me retuerzo'' o ''me duelo'', posiblemente reflejando una raíz homónima o corrupción textual. Algunos eruditos lo conectan con una raíz aramea que significa ''debilitarse'' o ''hundirse''. El contexto de profecía angustiada encaja tanto con ''espero en agonía'' como con ''me retuerzo de dolor''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101691, 'spa', 'Estar en celo, aparearse', 'Estar en celo o experimentar excitación reproductiva, dicho del ganado durante la temporada de apareamiento. Las cinco ocurrencias se concentran en la narrativa de Jacob y Labán (Gn 30:38-39, 41; 31:10), describiendo el ardor sexual de los rebaños junto a los abrevaderos. La expresión española ''encenderse en celo'' preserva con precisión el registro específicamente animal-reproductivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101693, 'spa', 'Calentarse, acalorarse', 'Adquirir calor físico, aplicado a cuerpos humanos u objetos que ganan temperatura. Los siervos del anciano David buscaron a alguien que lo ayudara a ''calentarse'' (1 Re 1:1), dos que se acuestan juntos ''tendrán calor'' (Ec 4:11), y el corazón del vengador puede ''acalorarse'' en la persecución (Dt 19:6). El significado térmico es directo y no figurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101695, 'spa', 'Concebir (un hijo)', 'Piel: concebir un hijo humano, extensión singular del celo animal a la generación humana. El Salmo 51:5 es el único caso: ''en pecado me concibió mi madre'', versículo central en la teología del pecado original. La transferencia de la reproducción zoológica a la humana está marcada por el uso del Piel, distinguiendo claramente el sentido de ''concebir'' del de ''estar en celo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101703, 'spa', 'Descalzo, sin sandalias', 'Describe el estado físico de carecer de sandalias, típicamente como señal de duelo, vergüenza o simbolismo profético. David camina descalzo en su aflicción (2 Sam 15:30); Isaías anda descalzo como presagio de cautiverio (Is 20:2-4). En Jer 2:25, se usa como sustantivo abstracto (''desnudez del pie''), advirtiendo metafóricamente contra la búsqueda agotadora de la idolatría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101707, 'spa', 'registro genealogico — El infinitivo constructo funcionando como sustantivo', 'registro genealogico — El infinitivo constructo funcionando como sustantivo: el registro genealogico o documento de inscripcion. En pasajes como 1 Cronicas 7:5 y 7:40, el texto se refiere a ''su registro'' (הִתְיַחֲשָׂם) como un documento concreto o recuento — la lista que certifica el linaje. Las formas con sufijo (הִתְיַחֲשָׂם) enfatizan la naturaleza oficial y documental de este acto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101711, 'spa', 'inscribirse por genealogia — El sentido verbal', 'inscribirse por genealogia — El sentido verbal: inscribirse o ser inscrito por genealogia — el proceso activo o pasivo de ser registrado segun el linaje ancestral. En 1 Cronicas 5:1 la construccion ''no ser inscrito como primogenito'' muestra el verbo gobernando el estatus dentro del sistema genealogico. Esdras 2:62 y Nehemias 7:64 describen sacerdotes que ''buscaron su registro'' pero no pudieron ser hallados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101723, 'spa', 'Yajat (nombre propio)', 'Nombre propio masculino que posiblemente significa ''él (Dios) arrebatará'', portado por cinco hombres diferentes en el AT: un descendiente de Judá (1 Cr 4:2) y cuatro levitas que sirvieron en distintas generaciones. La Septuaginta griega varía entre Ιεθ e Ιααθ, mientras que las tradiciones en español, inglés y alemán lo transliteran de manera consistente como Yajat/Jahath/Jachat.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101725, 'spa', 'Qal: ser bueno, agradar', 'El Qal estativo/intransitivo ''ser bueno, agradar'' cuenta con 38 ocurrencias y describe situaciones, acciones o estados que resultan buenos o agradables a alguien. Genesis 41:37 senala que «la cosa fue buena a ojos de Faraon»; Genesis 45:16 registra que «agrado a Faraon» la noticia de los hermanos de Jose. El arabe حَسُنَ distingue este sentido estativo del causativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101728, 'spa', 'Adverbial: bien, cabalmente', 'El infinitivo absoluto Hifil empleado adverbialmente para significar ''bien, cabalmente, a fondo'', con 10 ocurrencias. Genesis 32:12 traduce ''ciertamente te hare bien''; Deuteronomio 13:14 ordena investigar ''a fondo''. El arabe adverbial جَيِّدًا (''bien'') e إِحْسَانًا (''haciendo bien cabalmente'') confirman esta funcion intensificadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101729, 'spa', 'Hifil: hacer bien, tratar bien', 'La acepcion nuclear del Hifil causativo: hacer bien a alguien o tratarlo con bondad, con 42 ocurrencias. Genesis 12:16 registra que Faraon trato bien a Abram por causa de Sarai; Genesis 32:9-12 reitera la promesa de Dios: «Yo te hare bien». El arabe أَحْسَنَ (Forma IV) marca esta beneficencia transitiva: el sujeto actua en favor del objeto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101736, 'spa', 'Marchar con gallardía', 'Proverbios 30:29 enumera dos veces seres que ''marchan con gallardía'' o ''caminan bien''. El participio y el contexto (andar, porte) conducen a la glosa ''gallardo'' o ''que se mueve con gracia''. Puede ser una extension del sentido adverbial (acepcion 3, ''hacer bien'') o un lexema especializado. Las dos ocurrencias, identicas en un proverbio numerico, limitan la evidencia independiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101737, 'spa', 'Hifil: enmendar, mejorar', 'Siete ocurrencias muestran un sentido Hifil de enmendar, mejorar o corregir. Jeremias 7:3, 5 ordena «Enmendad vuestros caminos y vuestras obras»; Jeremias 18:11 llama a cada persona a «volver de su mal camino y enmendar sus obras». El arabe emplea la raiz distinta أَصْلَحَ (''reparar, reformar''), revelando que el campo semantico hebreo (''hacer bien'' → ''corregir'') es mas amplio que el de otras lenguas semiticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101742, 'spa', 'Qal: alegrarse (el corazon)', 'Cinco ocurrencias del Qal donde el corazon o el espiritu se alegra o se pone contento. Jueces 18:20 registra que el corazon del levita «se alegro»; Rut 3:7 senala que el corazon de Booz «estaba contento» con la comida y la bebida; 1 Reyes 21:7 insta: «alegrese tu corazon». El arabe طَابَ (''ser grato de corazon'') confirma esta rama semantica semitica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101755, 'spa', 'Adornarse, embellecerse', '2 Reyes 9:30 registra que Jezabel ''se adorno'' (literalmente ''se hizo buena'') antes de la llegada de Jehu. La unica ocurrencia y el contexto reflexivo (''adorno sus ojos con pintura'') sugieren un sentido especializado de arreglo personal o embellecimiento, aplicacion concreta del causativo ''hacer bueno'' al aspecto fisico propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101761, 'spa', 'Hifil: tocar con destreza', 'Salmo 33:3 ordena ''tocad con destreza'' la lira, e Isaias 23:16 insta a la ramera a ''tocar bien'' para ser recordada. El sentido Hifil de ejecutar musica con habilidad es una extension natural de ''hacer bien'' aplicado a la interpretacion instrumental. Dos ocurrencias confirman este nucleo semantico de ejecucion artistica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101763, 'spa', 'Preparar las lamparas', 'Exodo 30:7 describe el deber de Aaron de ''aderezar las lamparas'' cada manana. La unica ocurrencia y el contexto ritual aislan este uso, que parece ser una aplicacion especializada de ''hacer bien/poner en orden'' al mantenimiento de las lamparas del tabernaculo. Podria pertenecer a la acepcion 4 (enmendar) o a la 1 (hacer bien).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101764, 'spa', 'Hifil: alegrar, regocijar', 'Jueces 19:22 describe a los hombres de Guibea ''alegrando su corazon'', y Eclesiastes 11:9 aconseja ''alegrete tu corazon en los dias de tu juventud''. El sentido causativo Hifil de causar gozo o producir regocijo aparece dos veces. Representa un desplazamiento semantico desde la bondad general hacia la produccion activa de alegria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101774, 'spa', 'Ser mejor (comparativo)', 'Nahum 3:8 pregunta «¿Eres tu mejor que Tebas?», unica ocurrencia que compara ciudades. Se trata de un uso comparativo directo del Qal estativo (acepcion 2, ''ser bueno''), donde una ciudad esta mejor situada o es mas segura que otra. BDB enumera explicitamente este sentido (''estar bien situada''), confirmando que encaja dentro del nucleo estativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101790, 'spa', 'Parecer bien (impersonal)', '1 Samuel 20:13 registra el juramento de Jonatan: «si a mi padre le pareciere bien hacerte mal, yo te lo revelere». La unica ocurrencia emplea una construccion impersonal ''parecer bien'' que encaja plenamente en la acepcion 2 (ser bueno, agradar). El matiz epistemico (''parecer'') no constituye un campo semantico independiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101798, 'spa', 'Campamento del desierto', 'Campamento en el desierto cuya localización precisa se ha perdido en la historia. El nombre «lugar agradable» contrasta irónicamente con la geografía desértica circundante, quizá indicando una fuente de agua o sombra poco común. Su forma consistente en diversas lenguas muestra que el nombre estaba bien establecido en las tradiciones del itinerario del desierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101800, 'spa', 'Clan ismaelita', 'Nombre de un clan ismaelita que evolucionó hasta convertirse en un gentilicio para un pueblo del Líbano. La supervivencia del nombre hasta la época neotestamentaria (como Iturea) demuestra la notable continuidad de las identidades tribales en el antiguo Cercano Oriente. Esta tribu representa una línea de los descendientes de Abraham a través de Ismael que mantuvo una presencia diferenciada durante más de un milenio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101801, 'spa', 'Vino (jugo de uva fermentado)', 'Bebida de uva fermentada, el termino hebreo principal para el vino en todos sus contextos sociales, culticos y literarios. Aparece en escenas de sustento cotidiano (Gn 14:18; Jue 19:19), como elemento prescrito en las libaciones (Nm 15:5-10), como simbolo de gozo y bendicion divina (Sal 104:15; Am 9:14) y como fuente de peligro moral cuando se abusa de el (Pr 20:1; 23:30-31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101823, 'spa', 'Reprender, reprochar', 'Reprender, reprochar: el sentido más frecuente, referido a reprender o reprochar a alguien por una falta, ya sea corrección humana o divina. El árabe wabbakha (''reprender''), el coreano kkujitda (''regañar'') y el suajili -kemea (''reprender'') convergen en este acto de habla confrontativo. Lv 19:17 ordena reprender directamente al prójimo en vez de albergar resentimiento oculto; 2 R 19:4 registra la súplica de Ezequías para que Dios reprenda las burlas de Asiria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101827, 'spa', 'Decidir, juzgar, arbitrar', 'Decidir, juzgar, arbitrar: el sentido jurídico visible en Is 2:4 e 11:3, donde el Mesías ''juzgará'' entre las naciones. El árabe yahkumu (''juzgar''), el coreano pandanhada (''juzgar, decidir'') y el alemán richten (''juzgar'') confirman la fuerza adjudicativa. Gn 31:37 lo emplea para el arbitraje entre Labán y Jacob.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101829, 'spa', 'Disciplinar, corregir', 'Disciplinar, corregir: disciplinar o corregir con intención pedagógica, distinguido de la mera reprensión por su propósito formativo. Pr 3:12 vincula el יָכַח divino con el amor paternal; 2 S 7:14 lo aplica a la disciplina pactual de Dios sobre el heredero de David. El árabe yuʾaddibu (''educar/disciplinar'') y el suajili -adhibu (''disciplinar'') resaltan el matiz correctivo-pedagógico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101836, 'spa', 'Vindicar, exonerar públicamente', 'Vindicar, exonerar públicamente: en Gn 20:16, el pago de Abimelec a Abraham sirve para vindicar públicamente a Sara: su honor queda establecido ante todos. El sentido de vindicación forense o exoneración pública queda confirmado por el español vindicada, tendiendo un puente entre el lenguaje de reprensión y el resultado judicial de absolución.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101848, 'spa', 'Designar, señalar', 'Designar, señalar: una extensión semántica rara que significa nombrar o designar, presente solo en Gn 24:14 y 24:44, donde el siervo de Abraham pide a Dios que ''designe'' a la esposa adecuada para Isaac. El árabe ʿayyana (''nombrar'') y el coreano jeonghada (''determinar'') apoyan este desplazamiento especializado de ''demostrar correcto'' a ''distinguir mediante prueba''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101850, 'spa', 'Argumentar, contender, defender una causa', 'Argumentar, contender, defender una causa: el registro forense-retórico prominente en Job y el discurso profético. Job 13:3 y 13:15 emplean יָכַח para el acto audaz de presentar el argumento legal de uno ante Dios mismo. El árabe yuhajju (''disputar'') y el francés reprendre captan la fuerza disputativa que lo distingue de la simple reprensión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101873, 'spa', 'Contender en pleito pactual', 'Contender en pleito pactual: en Mi 6:2, Dios convoca a los montes como testigos y ''contiende'' con Israel en un pleito pactual (patrón de rîb). El español contenderá sitúa este uso en la intersección del argumento legal y la acusación profética, estrechamente relacionado con el sentido 2 pero intensificado por el género del pleito pactual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101876, 'spa', 'Jaquín (nombre propio)', 'Nombre propio que significa ''él establecerá'', usado tanto para un ancestro del clan simeonita (Gn 46:10; Éx 6:15; Nm 26:12) como para el pilar derecho del templo de Salomón (1 Re 7:21), emparejado con Boaz. Las distintas traducciones — inglés ''Jachin'', español ''Jaquín'', francés y alemán conservando la forma hebrea — reflejan una transliteración consistente entre tradiciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101881, 'spa', 'Poder, ser capaz', 'Capacidad o aptitud general: ''poder'', ''ser capaz''. Es la acepcion abrumadoramente dominante (168 ocurrencias), que funciona como el modal hebreo estandar para tener la fuerza, el permiso o la capacidad de hacer algo. Aparece con complementos de infinitivo: «No puedo huir al monte» (Gn 19:19), «La tierra no podia sostenerlos» (Gn 13:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101899, 'spa', 'Prevalecer, vencer', 'Prevalecer, vencer o imponerse sobre un adversario u obstaculo. La lucha de Jacob en Peniel ofrece el paradigma: «Has luchado con Dios y con los hombres, y has prevalecido» (Gn 32:28). En 2 Cronicas 18:21, un espiritu dice «Yo prevalecere» para enganar a Acab. El suajili -shinda y el coreano 이기다 traducen esto como ''ganar/vencer'', confirmando un desplazamiento semantico genuino desde la mera capacidad hacia la victoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101903, 'spa', 'Soportar, resistir', 'Soportar, resistir o aguantar un sufrimiento o una situacion intolerable. El grito de Ester — «¿Como podre yo soportar ver la destruccion de mi pueblo?» (Est 8:6) — es el ejemplo mas nitido. Isaias 1:13 presenta a Dios declarando: «No puedo soportar iniquidad y asamblea solemne». El sentido se desplaza del poder exterior a la fortaleza interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101960, 'spa', 'poder, ser capaz', 'Tener la capacidad o facultad de lograr algo, usado con un complemento de infinitivo. El verbo aparece en preguntas sobre si los sabios ''pueden'' revelar misterios (Dan 2:10, 27), en confesiones de omnipotencia divina — ''nuestro Dios puede librarnos'' (Dan 3:17) — y en declaraciones de imposibilidad humana frente al decreto divino (Dan 3:29; 4:15; 6:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101964, 'spa', 'prevalecer, vencer', 'Prevalecer contra alguien o vencerlo, pasando de la mera capacidad a la dominación activa en un conflicto. En Daniel 7:21, el cuerno pequeño hace guerra contra los santos ''y los vencía'' (וְיָכְלָה לְהוֹן), donde la preposición לְ marca el objeto adversarial. El sentido abandona el modal ''poder'' en favor de un lenguaje marcial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101968, 'spa', 'Reina madre', 'Nombre de una reina madre conservado en los registros regios de Judá que afirma el poder y la capacidad de Yahvé. Las variantes textuales (Yecolyahu/Yecolyá/Yekilía) evidencian la fluidez ortográfica de los nombres teofóricos con terminaciones -yahu/-yah. Su hijo Azarías/Uzías tuvo uno de los reinados más largos y prósperos de la historia de Judá, aunque terminó trágicamente cuando fue herido con lepra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101970, 'spa', 'Jeconías (nombre propio)', 'Nombre propio Yekhonyah/Yekhanyahu (יְכוֹנְיָה / יְכָנְיָהוּ), que significa ''YHWH establece'', referido al rey Jeconías (= Joaquín), penúltimo rey de Judá exiliado por Nabucodonosor en el 597 a.C. El nombre aparece en tres variantes ortográficas en Jeremías, Crónicas y Ester (Jer 24:1; 27:20; 28:4; 29:2; 1 Cr 3:16-17; Est 2:6). En español se traduce tradicionalmente como ''Jeconías''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101973, 'spa', 'Qal: engendrar (sujeto masculino)', 'Qal activo con sujeto masculino: engendrar, ser padre de un hijo. El arabe walada (conjugacion masculina) y el aleman zeugte marcan la generacion paterna. Esta acepcion construye las grandes cadenas genealogicas — el triple ''engendro'' de Genesis 4:18 y las formulas toledot — codificando linaje y sucesion pactual a traves del padre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101975, 'spa', 'Qal: dar a luz (sujeto femenino)', 'Qal activo con sujeto femenino: parir, dar a luz a un hijo. El arabe waladat (activo femenino) y el coreano nahda (''dar a luz'') marcan consistentemente el acto materno. Domina los relatos de nacimiento desde Eva dando a luz a Cain (Gn 4:1) a traves de las matriarcas (Gn 4:17, 25) y hasta los oraculos profeticos sobre mujeres de parto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101979, 'spa', 'Pasivo/Nifal: nacer', 'Qal pasivo y Nifal: nacer. El arabe wulida (pasivo de walada) y el coreano taeonada (''nacer'') confirman la orientacion pasiva. Aparece en resumenes genealogicos (''les nacieron hijos'', Gn 6:1; 10:1), en los decisivos oraculos de ''un nino nos es nacido'' y en las declaraciones salmicas de filiacion divina (Sal 2:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (101992, 'spa', 'Piel: ejercer de partera', 'Piel intensivo: ejercer de partera, asistir en el parto. El arabe cambia por completo a la raiz no emparentada q-b-l (qabila, ''partera, recibir''), demostrando que se trata de un rol profesional reconocido. Central en la narrativa del Exodo donde las parteras hebreas desafian al Faraon (Ex 1:15-21) y en los nacimientos de Benjamin (Gn 35:17) y Fares (Gn 38:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102006, 'spa', 'Hofal: nacimiento (pasivo causativo)', 'Hofal causativo-pasivo: el nacimiento como evento nominalizado, el hecho de ser dado a luz. El arabe milad (''cumpleanos'') y wilada (''nacimiento'') — ambas formas nominales de evento — aparecen en estos contextos. Las tres ocurrencias incluyen el banquete de cumpleanos del Faraon (Gn 40:20) y la vivida descripcion de Ezequiel del nacimiento desatendido de Jerusalen (Ez 16:4-5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102011, 'spa', 'Hifil: hacer engendrar (causativo)', 'Hifil causativo: hacer engendrar, producir descendencia. El arabe awlada (Forma IV causativa) marca la agencia externa. Aparece en advertencias profeticas donde Dios causa o permite que se produzca progenie (Gn 17:20 para Ismael; Dt 28:41) y en profecias cortesanas sobre linaje real (2 R 20:18; Is 39:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102018, 'spa', 'El nacido (sustantivado)', 'Un uso sustantivado que designa ''al nino'': el nacido como persona y no el acto de nacer. Aparece en el famoso juicio de Salomon (1 R 3:26-27), donde el nino vivo es el objeto focal. La lectura nominal del recien nacido como entidad distinta confirma la versatilidad categorial de la raiz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102118, 'spa', 'Registrar el linaje', 'Un sentido de registro inusual que aparece solo en Numeros 1:18, donde el verbo se emplea en el contexto de declarar o registrar la ascendencia: ''se registraron por sus linajes''. El acto reflexivo-genealogico de establecer la linea de nacimiento propia, distinto del acto fisico de la generacion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102145, 'spa', 'Niño, muchacho, joven', 'Niño, muchacho, joven: un ser humano joven desde la infancia hasta la adolescencia. Cubre formas singulares y plurales, masculinas, a veces con referentes femeninos implícitos. El español ''niño'', el francés enfant, el alemán Kind y el árabe طفل indican uniformemente una persona joven más que una categoría relacional como ''hijo''. Pasajes centrales incluyen Gn 21:8 (''el niño creció y fue destetado'') y Éx 2:6 (''vio al niño'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102167, 'spa', 'Cría de animales', 'Cría de animales: crías o animales jóvenes, extendiendo el significado central de ''niño/joven'' al reino animal. Se distingue por el contexto más que por la morfología. El francés son enfant y el español sus crías pasan a vocabulario específico de animales. Job 38:41 (''cuando sus crías claman a Dios'') y Job 39:3 (''se agachan, dan a luz sus crías'') emplean la palabra para crías de animales salvajes, mientras que Is 11:7 la usa para un animal doméstico junto a la fiera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102183, 'spa', 'Muchacha joven', 'Mujer joven, generalmente en edad casadera o próxima a ella. Los contextos abarcan desde lo traumático (Dina llamada «la niña» en la narración de Siquem) hasta lo profético-escatológico (niños jugando en las plazas de Jerusalén como señal de bendición divina). La visión de Zacarías de niñas y niños juntos simboliza la plenitud de la restauración prometida por Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102184, 'spa', 'Juventud y vigor', 'El estado o período de ser joven, con énfasis en el vigor y el potencial más que en la mera edad. El uso de Qohélet enmarca la juventud como un tiempo de gozo y responsabilidad moral a la vez: transitorio pero significativo. La metáfora del «rocío de tu juventud» en el Salmo evoca frescura y renovación, describiendo posiblemente a guerreros jóvenes o la vitalidad de un pueblo renovado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102185, 'spa', 'Nacido, el engendrado', 'Describe a personas definidas por el acto o la circunstancia de su nacimiento, siempre con artículo para particularizar. En Éx 1:22, el decreto del faraón apunta a ''todo hijo que nazca'' entre los hebreos; en Jos 5:5 distingue a la generación nacida en el desierto de quienes salieron de Egipto. Las glosas multilingües confirman el sentido participial pasivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102187, 'spa', 'nacido en la casa, nativo', 'Nacido dentro de un hogar o descendiente de un linaje específico (יָלִיד). En la legislación sacerdotal, יְלִיד בַּיִת (''nacido en la casa'') designa al esclavo nacido bajo el techo del amo, a diferencia del adquirido por compra (Gn 17:12-13, 27; Lv 22:11). En contextos narrativos marca la descendencia biológica de grupos notables: los ''nacidos de los refaítas'' (2 S 21:16, 18; 1 Cr 20:4) y los hijos de Anac (Nm 13:22, 28; Jos 15:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102195, 'spa', 'ir, partir, viajar', 'Qal básico: ir, partir, viajar — el sentido primario con 884 ocurrencias, cubriendo todo movimiento dirigido de un lugar a otro. Abraham ''fue'' conforme el SEÑOR le había hablado (Gn 12:4); Jacob ''siguió su camino'' (Gn 32:1); mensajeros ''fueron'' y volvieron. El árabe dhahaba y el coreano 가다 son los equivalentes estándar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102203, 'spa', '¡ven!, ¡vamos!', 'Imperativo como invitación: ''¡ven!, ¡vamos!'' — 63 ocurrencias donde el imperativo לֵךְ/לְכוּ funciona pragmáticamente no como ''¡vete!'' sino como ''¡ven!'' o ''¡vamos, hagamos...'' invitando a una acción conjunta. ''Venid, vendámoslo'' (Gn 37:27); ''Ven, demos de beber vino a nuestro padre'' (Gn 19:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102204, 'spa', 'andar en, seguir un camino', 'Qal figurado: andar en un camino, seguir una conducta — 79 ocurrencias donde הָלַךְ se combina con una frase preposicional (בְּדַרְכֵי, בְּחֻקּוֹת, ''en los caminos/estatutos de'') para describir conducta moral o estilo de vida. ''Si anduviereis en mis estatutos'' (Lv 26:3); ''anduvieron en los estatutos de las naciones'' (2 R 17:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102241, 'spa', 'irse, partir definitivamente', 'Qal enfático: irse, partir permanentemente, desvanecerse — 5 ocurrencias donde הָלַךְ conlleva la connotación de partida irreversible o desaparición. ''Que vaya en medio de nosotros'' (Éx 34:9, implorando que Dios no se retire definitivamente); ''todas las rodillas se irán como agua'' (Ez 7:17; 21:7, es decir, se disolverán).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102276, 'spa', 'Hifil: guiar, conducir', 'Hifil causativo: guiar, llevar, hacer ir — 13 ocurrencias donde un agente causa el movimiento de otro. Dios ''hizo andar'' a Israel cuarenta años por el desierto (Dt 29:5); Moisés los ''condujo'' erguidos (Lv 26:13); un fuerte viento del este ''hizo retroceder'' el mar (Éx 14:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102345, 'spa', 'aullar, gemir fuertemente — Proferir un gemido fuerte y prolongado de dolor o an', 'aullar, gemir fuertemente — Proferir un gemido fuerte y prolongado de dolor o angustia, usado casi exclusivamente en oráculos proféticos de juicio. Isaías ordena a las naciones aullar ante la cercanía del Día de YHWH (Is 13:6; 14:31; 15:2-3; 23:1). Jeremías lo dirige contra Moab (Jer 48:20, 31) y pastores condenados (Jer 25:34). Joel convoca al gemido por la devastación agrícola (Jl 1:5, 11). Suele aparecer en paralelo con za''aq y tsa''aq, formando un vocabulario de intenso lamento comunitario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102359, 'spa', 'Aullido, lamento', 'Vocalización fuerte de angustia y lamentación, frecuentemente colectiva. Suele aparecer en paralelo con términos como זְעָקָה (''clamor'') y צְעָקָה (''alarido'') en oráculos de juicio profético. En Is 15:8, el aullido de Moab rodea la tierra; en Jer 25:36 y Zac 11:3, los ''pastores'' (metáfora de gobernantes) aúllan ante la devastación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102362, 'spa', 'Langosta (especie gregaria)', 'Sustantivo colectivo para una especie de langosta gregaria o fase larval, distinta de אַרְבֶּה (el término genérico para ''langosta'') pero perteneciente al mismo complejo destructivo. En Joel 1:4 aparece en una secuencia de cuatro fases de devastación, lo que sugiere un estadio específico de desarrollo. El Salmo 105:34 lo emplea en relación con la plaga de Egipto junto a אַרְבֶּה. Nahúm lo usa metafóricamente tanto para la abundancia abrumadora como para la dispersión repentina de multitudes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102368, 'spa', 'mar, masa de agua', 'Gran extensión de agua, ya sea el Mediterráneo (el ''Gran Mar'', Nm 34:6), el mar Rojo, el mar Muerto o mares en general, incluido el ''mar'' de bronce fundido del templo (1 R 7:23). Es la acepción dominante, que abarca formas singulares y plurales con todos los adjuntos preposicionales y pronominales, así como usos poéticos y cosmológicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102371, 'spa', 'oeste, hacia el oeste', 'La dirección ''oeste'' u ''occidental'', derivada de la orientación geográfica israelita donde el Mediterráneo quedaba al poniente. Aparece destacadamente en la construcción del tabernáculo (Éx 26:22, ''la parte posterior del tabernáculo, al oeste'') y en las descripciones de límites tribales. El sufijo direccional he (yammah) refuerza con frecuencia este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102374, 'spa', 'mar de (topónimo)', 'El sustantivo yam en estado constructo como primer elemento de un nombre propio geográfico: yam suf (mar de los Juncos, Éx 13:18), yam kinneret (mar de Cineret, Nm 34:11), yam ha-aravah (mar del Arabá, Dt 3:17). Se distingue de la acepción 1 por el estrecho vínculo constructo con el nombre propio que le sigue.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102422, 'spa', 'lado derecho (dirección)', 'El lado derecho como dirección espacial o posición (73 apariciones). Abarca girar a la derecha, estar al lado derecho de alguien, el costado derecho de un lugar y la posición de honor o cercanía. Abraham dice a Lot: ''Si vas a la derecha, yo iré a la izquierda'' (Gn 13:9); la oreja, el pulgar y el dedo gordo derechos del sacerdote reciben la sangre de la consagración (Éx 29:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102424, 'spa', 'diestra (parte corporal y poder)', 'La mano derecha física como parte del cuerpo e instrumento de poder divino o real (62 apariciones). Es la yamin de Éxodo 15:6, cuya diestra actúa, golpea, sostiene y bendice. Aquí la mano no es meramente direccional sino agentiva, fusionando lo corporal con lo teológico, tal como refleja el español diestra frente a derecha.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102437, 'spa', 'sur (punto cardinal)', 'El sur como dirección cardinal geográfica (5 apariciones), derivada de la orientación espacial hebrea en la que uno mira al este y la mano derecha señala al sur. En 1 Samuel 23:19 y 23:24 David se esconde ''al sur de Jesimón''; en el Salmo 89:12 Dios creó ''el norte y el sur''. Todas las lenguas recurren a lexemas distintos para esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102486, 'spa', 'Jamín (nombre propio)', 'Nombre personal Yāmîn (יָמִין, ''mano derecha''), llevado por al menos tres individuos: un hijo de Simeón que fue a Egipto (Gen 46:10; Exod 6:15; Num 26:12; 1 Chr 4:24), progenitor del clan jaminita; un descendiente de Jerameel por medio de Ram (1 Chr 2:27); y un levita o líder comunitario que ayudó a exponer la Torá durante la lectura pública de Esdras (Neh 8:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102490, 'spa', 'Gentilicio tribal', 'Designación étnico-tribal para los miembros de la tribu de Benjamín. Las tres apariciones se relacionan con Saúl y su contexto, subrayando su filiación tribal en un momento de importancia política. La forma abreviada (יְמִינִי en lugar de בֶּן־יְמִינִי) sugiere que era una designación común y bien comprendida en el Israel antiguo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102492, 'spa', 'Padre de Micaías', 'Nombre propio del padre del profeta Micaías, usado exclusivamente en el patronímico ''Micaías hijo de Imla'' tanto en Reyes como en Crónicas. La variante de Crónicas (יִמְלָא) presenta una ligera diferencia ortográfica. Las cuatro apariciones enmarcan la dramática escena donde Micaías pronuncia la verdadera palabra de Yahvé frente a los profetas cortesanos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102494, 'spa', 'Ir a la derecha', 'Moverse o girar hacia la derecha, ya sea literalmente en la orientación espacial o figuradamente en la dirección moral. En Gn 13:9 se empareja con su antónimo הִשְׂמִאיל (''ir a la izquierda'') cuando Abram reparte la tierra con Lot. En 1 Cr 12:2, el participio מַיְמִינִים describe a guerreros capaces de usar la mano derecha con igual destreza que la izquierda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102495, 'spa', 'Nombre propio bíblico', 'Nombre propio que designa a dos individuos distintos. El principal Imna es hijo de Aser, cuyo clan (los imnitas) se enumera en el censo tribal de Nm 26:44, apareciendo también en Gn 46:17 y 1 Cr 7:30. Un segundo Imna es un levita que asistió en la distribución de las ofrendas voluntarias durante las reformas de Ezequías (2 Cr 31:14). El posible cognado árabe yumn (''prosperidad'') refleja un nombre auspicioso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102496, 'spa', 'el derecho, la derecha — Relativo a la mano derecha o al lado derecho, usado tan', 'el derecho, la derecha — Relativo a la mano derecha o al lado derecho, usado tanto para partes del cuerpo en contextos rituales como para la orientación arquitectónica. En la consagración sacerdotal y los ritos de purificación, la oreja derecha, el pulgar derecho y el dedo gordo del pie derecho reciben sangre y aceite (Ex 29:20; Lv 8:23-24; 14:14-28). En descripciones del templo, identifica la columna derecha Jaquín (1 R 7:21) y el lado derecho del santuario (1 R 6:8; Ez 47:1-2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102503, 'spa', 'oprimir, agraviar, maltratar — La accion verbal de oprimir, agraviar o maltratar', 'oprimir, agraviar, maltratar — La accion verbal de oprimir, agraviar o maltratar a alguien, principalmente en formas finitas del Hifil y cohortativo del Qal. Este sentido domina el material legal: la prohibicion repetida contra oprimir al extranjero (Ex 22:21; Lv 19:33; Dt 23:16) y las leyes contra agraviar al projimo en el comercio (Lv 25:14, 17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102505, 'spa', 'opresor (participio sustantivado) — La forma participial funcionando como sustan', 'opresor (participio sustantivado) — La forma participial funcionando como sustantivo: el opresor, el que oprime. Se usa en la literatura profetica para nombrar a agentes de injusticia sistematica. Sofonias 3:1 llama a Jerusalen ''la ciudad opresora'' (ha-yonah), mientras que Jeremias usa la frase ''la espada del opresor'' (Jer 46:16; 50:16). En Isaias 49:26, Dios invierte la situacion: ''Hare que tus opresores devoren su propia carne.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102519, 'spa', 'Dejar, abandonar', 'Dejar, abandonar: dejar atrás, abandonar o desamparar, extensión de ''colocar'' hacia la separación. La persona que parte deposita algo o a alguien y se marcha. Se insta a Lot a dejar Sodoma (Gn 19:16), el grano se deja para los pobres (contexto de Lv 19:10) y Dios advierte sobre abandonar a su pueblo (Nm 32:15). El árabe taraka (''abandonar'') y el español dejar distinguen consistentemente este sentido de la mera colocación física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102521, 'spa', 'Dar reposo, establecer', 'Dar reposo, establecer: dar descanso, establecer o conceder reposo, donde el Hifil preserva de manera más transparente el significado raíz de נוח. Dios establecerá a Israel compasivamente en su tierra (Is 14:1), y Eclesiastés aconseja no dejar que la mano descanse del trabajo (Ec 11:6). El árabe askana/arāḥa (''establecer/dar reposo'') y el español hacer descansar seleccionan vocabulario específico de descanso, distinto de la colocación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102522, 'spa', 'Colocar, poner, depositar', 'Colocar, poner, depositar: el sentido causativo central en Hifil de colocar, poner o depositar un objeto o persona en un lugar específico. Dios coloca a Adán en el Edén (Gn 2:15), el maná se deposita ante el Testimonio (Éx 16:33) y Moisés pone el cayado ante el SEÑOR (Nm 17:7). El español depositó/puso, el francés déposer y el árabe waḍaʿa convergen en la colocación física, confirmándolo como el significado prototípico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102523, 'spa', 'Ser colocado, ser dejado (pasivo)', 'Ser colocado, ser dejado (pasivo): Hofal pasivo: ser colocado, puesto o dejado en un lugar, la contraparte pasiva de los sentidos 1-2, donde el sujeto experimenta la colocación en vez de realizarla. Las medidas del templo de Ezequiel incluyen ''el espacio que quedaba'' (Ez 41:9-11), y el efa ''es colocado'' sobre su base en la visión de Zacarías (Zac 5:11). El español quedaba y el francés déposer (pasivo) reflejan la voz pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102540, 'spa', 'Derribar, arrojar', 'Derribar, arrojar: depositar o arrojar con fuerza, una variante intensificada de la colocación donde el agente actúa con fuerza o violencia. Isaías describe una tormenta poderosa que ''derriba a tierra'' (Is 28:2), Dios reúne y deposita metales en el horno (Ez 22:20), y Amós declara que la justicia es ''derribada'' por tierra (Am 5:7). El árabe ṭaraḥa/alqā (''arrojar, lanzar'') capta la dimensión violenta que distingue este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102552, 'spa', 'Permitir, dejar en paz', 'Permitir, dejar en paz: una extensión relacional donde la metáfora de ''reposar'' se vuelve social: una parte deja a otra sin perturbar. Dios pide a Moisés ''déjame'' (Éx 32:10), Sansón pide apoyarse en las columnas (Jue 16:26), y el salmista nota que Dios ''no permitió'' que nadie oprimiera a su ungido (Sal 105:14). El coreano 허락하다 (''permitir'') y el árabe daʿa (''dejar ser'') confirman este sentido como concesión de no interferencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102582, 'spa', 'lactante, niño de pecho — Participio Qal usado como sustantivo para designar a u', 'lactante, niño de pecho — Participio Qal usado como sustantivo para designar a un niño lactante, aún dependiente del pecho. Aparece en contextos tanto tiernos como terribles: la alabanza ordenada de la boca de los niños (Sal 8:2) y la destrucción despiadada de ''hombre y mujer, niño y lactante'' (1 S 15:3; 22:19). Joel convoca incluso a los lactantes a la asamblea solemne (Jl 2:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102585, 'spa', 'nodriza, madre que amamanta — Participio Hifil que funciona como sustantivo para', 'nodriza, madre que amamanta — Participio Hifil que funciona como sustantivo para designar a una nodriza o madre lactante, la mujer que amamanta a un niño, a menudo profesionalmente. La nodriza de Rebeca, Débora, es recordada a su muerte (Gn 35:8), y la hermana de Moisés consigue astutamente una ''mujer que amamante'' que resulta ser su propia madre (Ex 2:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102586, 'spa', 'mamar, lactar — Verbo finito Qal que describe el acto físico de un niño mamando ', 'mamar, lactar — Verbo finito Qal que describe el acto físico de un niño mamando leche del pecho. Job desea haber mamado del pecho que lo recibió (Job 3:12), y la visión escatológica de Isaías promete que los hijos de Sion mamarán la leche de las naciones y el pecho de los reyes (Is 60:16). Deuteronomio 33:19 habla de mamar la abundancia de los mares.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102592, 'spa', 'amamantar, dar de mamar — Verbo finito e infinitivo Hifil que expresa la acción ', 'amamantar, dar de mamar — Verbo finito e infinitivo Hifil que expresa la acción causativa de dar de mamar o amamantar a un niño. Sara se maravilla de haber dado de mamar (Gn 21:7), la madre de Moisés es contratada para amamantarlo (Ex 2:9), y Ana posterga su peregrinación hasta destetar al niño que amamanta (1 S 1:23). Deuteronomio 32:13 lo usa metafóricamente: Dios amamantando a Israel con miel de la roca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102611, 'spa', 'Búho de ruinas', 'Ave de presa impura, muy probablemente una especie grande de búho, asociada con la desolación y las ruinas. En Isaías, la combinación de diversas rapaces y aves carroñeras crea un cuadro sombrío de lugares abandonados recuperados por la naturaleza salvaje. La identificación como ''gran búho'' refleja el consenso erudito, aunque los traductores antiguos a veces conjeturaron ante términos ornitológicos difíciles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102612, 'spa', 'cimentar, fundar (Piel intensivo) — El sentido intensivo Piel de fundar o ciment', 'cimentar, fundar (Piel intensivo) — El sentido intensivo Piel de fundar o cimentar deliberadamente, enfatizando la exhaustividad e intencionalidad del acto constructivo. La maldición de Josué lo invoca: ''maldito el hombre que edifique esta ciudad de Jericó; a costa de su primogénito echará sus cimientos'' (Jos 6:26), cumplida cuando Hiel ''puso sus cimientos'' a costa de Abiram (1 R 16:34).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102613, 'spa', 'fundar, establecer (Qal activo) — El sentido activo Qal de fundar, establecer o ', 'fundar, establecer (Qal activo) — El sentido activo Qal de fundar, establecer o poner cimiento, el uso más frecuente que abarca tanto la construcción terrenal como la cosmogonía divina. Dios ''fundó la tierra sobre los mares'' (Sal 24:2); ''con sabiduría YHWH fundó la tierra'' (Pr 3:19); a Job se le desafía: ''¿dónde estabas cuando yo fundaba la tierra?'' (Job 38:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102614, 'spa', 'fundar (participio cosmológico) — Ocurrencias donde el participio activo o el in', 'fundar (participio cosmológico) — Ocurrencias donde el participio activo o el infinitivo constructo llevan el sentido estándar de fundación en contextos cosmológicos teológicamente cargados: Isaías 51:13 (''YHWH tu Hacedor, que extendió los cielos y fundó la tierra'') y Zacarías 12:1 (''YHWH, que extiende los cielos y funda la tierra y forma el espíritu del hombre dentro de él'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102615, 'spa', 'ser fundado, ser cimentado (Pual/Hofal pasivo) — Las conjugaciones pasivas que e', 'ser fundado, ser cimentado (Pual/Hofal pasivo) — Las conjugaciones pasivas que expresan ''fue fundado, fue establecido, fueron puestos sus cimientos''. Aparecen en notas cronológicas de construcción: ''en el año cuarto se puso el cimiento de la casa de YHWH'' (1 R 6:37); ''cuando fue puesto el cimiento de esta casa delante de vuestros ojos'' (Hag 2:3; cf. Esd 3:6, 11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102623, 'spa', 'conspirar, consultarse (Nifal reflexivo) — El sentido reflexivo-recíproco Nifal ', 'conspirar, consultarse (Nifal reflexivo) — El sentido reflexivo-recíproco Nifal de consultarse o conspirar, una extensión semántica notable. El Salmo 2:2 declara: ''los reyes de la tierra se levantan, y los gobernantes se consultan juntos contra YHWH y su ungido.'' El Salmo 31:13 describe a enemigos que ''conspiran juntos contra mí, tramando quitarme la vida.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102624, 'spa', 'ser fundado (Nifal pasivo) — El sentido pasivo Nifal, ''ser fundado, ser establec', 'ser fundado (Nifal pasivo) — El sentido pasivo Nifal, ''ser fundado, ser establecido'', distinto del pasivo Pual/Hofal del sentido 3. Éxodo 9:18 sitúa la fundación de Egipto en perspectiva histórica: ''desde el día que fue fundada hasta ahora''; Isaías 44:28 presenta a Ciro declarando del templo ''sea puesto su cimiento''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102650, 'spa', 'Fundamento o base', 'Fundamento o base: la capa más baja o cimiento de una estructura, literalmente la parte inferior de un edificio, muro o altar. Ampliamente atestiguado en la legislación sacrificial donde se derrama la sangre al pie del altar (Éx 29:12; Lv 4:7, 18, 25, 30). Se extiende metafóricamente al ''fundamento'' de la fragilidad humana (Job 4:19; 22:16) y al justo como cimiento eterno que no puede ser removido (Pr 10:25). En el juicio profético, Dios promete dejar al descubierto los cimientos de Samaria (Mi 1:6) y Jerusalén (Lm 4:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102666, 'spa', 'añadir, aumentar (Hifil)', 'El causativo Hifil expresa añadir cantidad, incrementar una medida o aumentar, como en las fórmulas de penalización de Levítico donde se ''añadirá un quinto'' (Lv 5:16; 27:31). El sentido es puramente cuantitativo y aditivo, confirmado por el árabe zada (''aumentar'') y el español añadir/aumentar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102667, 'spa', 'y añadió, y continuó (Hifil consecutivo)', 'El imperfecto Hifil con waw consecutivo (wayyosef) narra adición o continuación secuencial en tiempo pasado: ''y volvió a dar a luz'' (Gn 4:2), ''y esperó otros siete días más'' (Gn 8:10). Esta forma narrativa predomina en Génesis y los Profetas Anteriores, donde el español alterna entre Y añadió e Y continuó.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102670, 'spa', 'continuar, volver a (Hifil)', 'Como verbo auxiliar en Hifil, yasaf significa ''continuar'' o ''volver a hacer'', rigiendo un infinitivo o una acción implícita. En Éxodo 8:29, Faraón no debe ''seguir engañando''; en Génesis 8:21, Dios resuelve ''no volver a maldecir la tierra''. Las lenguas receptoras deben elegir entre marcos de repetición y de continuación para esta única forma hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102672, 'spa', 'añadirá, continuará (Qal conjuntivo)', 'El weqatal Qal (perfecto conjuntivo) proyecta la adición o continuación hacia el futuro o lo condicional: ''y añadiré'' o ''y continuarán''. Levítico 26:18 advierte ''seguiré castigándoos siete veces más'', mientras que Levítico 27:13-15 prescribe ''y añadirá un quinto''. El cambio de aspecto distingue esta forma del sentido narrativo pasado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102679, 'spa', 'continuó, volvió a (Qal)', 'Formas del Qal simple que expresan continuación o repetición sin fuerza causativa: ''no volvió más'' (Gn 8:12), ''no la conoció más'' (Gn 38:26). Se trata de un complemento más ligero y no causativo del sentido auxiliar Hifil, donde el español emplea perífrasis como volvió a o continuó.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102688, 'spa', 'ser añadido, unirse (Nifal)', 'El Nifal pasivo-reflexivo: ''ser añadido a'', ''unirse'', ''ser incrementado''. En Éxodo 1:10, Faraón teme que los israelitas ''se unan a nuestros enemigos''; en Números 36:3-4 se legisla sobre herencias que podrían ''ser añadidas'' a otra tribu. El árabe inḍamma (''incorporarse'') refleja bien esta doble posibilidad pasiva y reflexiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102690, 'spa', 'aumentó, añadió (perfecto activo)', 'Formas del perfecto activo Qal y Hifil que denotan actos consumados de incremento cuantitativo: ''Aumentaste la nación'' (Is 26:15), ''añadieron pecado sobre pecado'' (1 S 12:19). El aspecto perfectivo distingue estas formas de la adición en curso o futura, centrándose en el resultado logrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102797, 'spa', 'disciplinar, castigar (Piel activo)', 'disciplinar, castigar (Piel activo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102804, 'spa', 'instruir, enseñar, formar', 'instruir, enseñar, formar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102808, 'spa', 'ser disciplinado, ser corregido (Nifal pasivo)', 'ser disciplinado, ser corregido (Nifal pasivo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102809, 'spa', 'amonestar, reprender (Qal activo)', 'amonestar, reprender (Qal activo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102813, 'spa', 'ser advertido, escarmentar (Nifal/Nitpael reflexivo)', 'ser advertido, escarmentar (Nifal/Nitpael reflexivo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102819, 'spa', 'atar, castigar (Hifil)', 'atar, castigar (Hifil)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102834, 'spa', 'Palas (utensilios cúlticos)', 'Sustantivo masculino plural que designa palas o recogedores de ceniza diseñados específicamente para la limpieza del altar de sacrificios. Aparece siempre en listas de inventario junto a otros implementos cúlticos como ollas (סִירוֹת), tazones (מִזְרָקוֹת) y tenedores (מִזְלָגוֹת). La fuente sacerdotal los enumera para el altar del tabernáculo (Éx 27:3; 38:3; Nm 4:14) y el historiador deuteronomista para el templo de Salomón (1 Re 7:40, 45).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102836, 'spa', 'Nombre propio', 'Nombre propio que identifica tanto a un hombre calebita famoso por su oración como a una ciudad judía asociada con familias de escribas. El nombre personal se vincula etimológicamente con עֶצֶב (''dolor'') en 1 Cr 4:9, donde su madre lo nombró por la aflicción de su parto, pero él trascendió ese nombre mediante la oración (v. 10). El topónimo en 1 Cr 2:55 ubica familias de escribas (סֹפְרִים) en Jabes, cerca de Belén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102837, 'spa', 'Nifal de cita divina', 'Nifal de cita divina: encontrarse en un lugar o tiempo designado, especialmente Dios reuniéndose con su pueblo en el Tabernáculo. Concentrado en los pasajes de la Tienda de Reunión del Éxodo (Ex 25:22; 29:42-43; 30:6, 36; Nm 17:4), donde Dios dice «me reuniré contigo» sobre el propiciatorio. Este sentido marca un encuentro divino solemne y programado, distinto de una asamblea casual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102839, 'spa', 'Nifal reflexivo-recíproco', 'Nifal reflexivo-recíproco: congregarse o reunirse como grupo con un propósito comunitario. La congregación de Israel es el sujeto típico, convocada por toques de trompeta (Nm 10:3-4) o reunida en queja (Nm 14:35; 16:11; 27:3). Las traducciones multilingües apuntan a una reunión corporativa, mientras el hebreo lo marca como acción recíproca: personas que se encuentran «unas con otras».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102841, 'spa', 'Hifil causativo con fuerza judicial', 'Hifil causativo con fuerza judicial: convocar o citar a alguien ante un tribunal o corte. Job lo usa para preguntar quién puede citar a Dios a comparecer (Job 9:19), y Jeremías lo aplica a Dios como el pastor a quien nadie puede pedir cuentas (Jer 49:19; 50:44). El español «citar» distingue este sentido judicial de la simple designación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102844, 'spa', 'Hofal pasivo', 'Hofal pasivo: ser designado, puesto o dirigido por mano de otro. Atestiguado en Jeremías 24:1 respecto a higos «puestos» delante del templo y Ezequiel 21:16 respecto a una espada «designada» para golpear. La construcción pasiva marca al receptor de la designación en vez del designador, extensión natural del sentido activo Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102845, 'spa', 'Nifal recíproco con matiz de acuerdo mutuo o conspiración', 'Nifal recíproco con matiz de acuerdo mutuo o conspiración: reunirse por pacto prearreglado. Amós 3:3 pregunta si dos caminan juntos sin haberse puesto de acuerdo, y Job 2:11 describe a los tres amigos que concertaron venir juntos. El español «concertarse» distingue este sentido de la simple asamblea del sentido 1 al enfatizar la deliberación y el acuerdo previo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102848, 'spa', 'Qal activo', 'Qal activo: designar, nombrar o asignar a alguien o algo para un propósito específico. Cubre fijar un tiempo (2 Sam 20:5), señalar un lugar (Jer 47:7), dirigir una vara de juicio (Mi 6:9) y la designación legal de una concubina (Ex 21:8-9). El español «designar» marca el acto autoritativo de asignación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102865, 'spa', 'Yeush (nombre propio)', 'Nombre propio de etimología incierta, llevado por varios individuos: un jefe edomita, hijo de Esaú y Oholibama (Gn 36:5, 14, 18; 1 Cr 1:35); un benjaminita del linaje de Saúl (1 Cr 7:10; 8:39); un hijo del rey Roboam de Judá (2 Cr 11:19); y un levita entre los hijos de Simei (1 Cr 23:10-11). El portador edomita es el más significativo históricamente, pues su clan figura entre las jefaturas de Edom.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102873, 'spa', 'Jazer (topónimo)', 'El topónimo Jazer (יַעְזֵר / יַעְזֵיר), ciudad fortificada transjordana en la región de Galaad. Aparece en las narrativas de la conquista como territorio tomado de los amorreos y asignado a Gad (Nm 21:32; 32:1, 3, 35; Jos 13:25). También sirvió como ciudad levítica (Jos 21:39; 1 Cr 6:66) y se vincula con imágenes de viñedos en los oráculos proféticos contra Moab (Is 16:8-9; Jer 48:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102881, 'spa', 'Yeiel (nombre propio)', 'Yeiel (nombre propio): nombre propio masculino hebreo llevado por al menos ocho individuos distintos en Crónicas y Esdras. El músico levita en la procesión del arca bajo David es el más prominente (1 Cr 15:18, 21; 16:5), junto con el ancestro gabaonita de Saúl (1 Cr 9:35), uno de los valientes de David (1 Cr 11:44), el escriba militar de Uzías (2 Cr 26:11), levitas en las reformas de Ezequías y Josías (2 Cr 29:13; 35:9), y un retornado del exilio (Esd 8:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102891, 'spa', 'Conferir provecho o ventaja; ser de utilidad', 'Conferir provecho o ventaja; ser de utilidad. Solo en Hifil, casi siempre negado: de ídolos que no pueden ayudar (1 Sam 12:21; Is 44:9; Jer 2:8; Hab 2:18), riquezas que fallan (Pr 11:4) y esfuerzo cuestionado ante Dios (Job 21:15; 35:3). El raro uso positivo en Isaías 48:17 intensifica el contraste: «Yo soy YHWH tu Dios, que te enseña para tu provecho». El español «aprovechar» y el francés «profiter» reflejan con precisión este registro utilitario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102909, 'spa', 'Íbice salvaje', 'El íbice o cabra montés, emblema de la creación indómita que prospera en lugares inaccesibles. El conocimiento divino de sus épocas de parto (Job 39) y la provisión de riscos elevados como refugio (Salmo 104) ilustran el cuidado de Dios que alcanza incluso a criaturas fuera del alcance humano. El topónimo ''Peñas de las Cabras Monteses'' confirma que estos animales eran habitantes emblemáticos del desierto de Judea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102910, 'spa', 'Nombre propio Yael', 'El nombre propio Yāʿēl (יָעֵל, probablemente ''cabra montés, íbice''), que identifica a la esposa de Heber el ceneo que mató a Sísara. Aparece en la narración en prosa de Jueces 4:17–22, donde atrae al general fugitivo a su tienda y le clava una estaca en el cráneo, y en el Cántico de Débora (Jue 5:24), donde es llamada ''bendita entre las mujeres''. Jueces 5:6 también podría hacer referencia a ella.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102913, 'spa', 'Jefe edomita', 'Yalam es identificado de manera constante como hijo de Esaú nacido de Oholibama en la tierra de Canaán (Gn 36:5, 14, 18) y contado entre los jefes edomitas. El relato paralelo en 1 Cr 1:35 conserva el mismo registro genealógico. La Septuaginta lo vocaliza como Ιεγλομ, y las traducciones multilingües muestran diversas estrategias de transliteración según cada familia lingüística.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102914, 'spa', 'porque, por cuanto', 'Conjunción causal que significa ''porque, por cuanto, ya que'', introduciendo típicamente la razón o el cargo en oráculos proféticos de juicio. Su patrón distintivo es ya''an...laken (''por cuanto...por tanto''), donde se expone la ofensa antes de pronunciar la sentencia (Ez 25:3; 26:2; 28:2). Las apariciones no proféticas incluyen textos de alianza clave como Génesis 22:16 y Números 20:12.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102920, 'spa', 'El avestruz', 'El avestruz, ave grande del desierto conocida por su grito inquietante y su asociación con lugares desolados. Se emplea como símbolo de duelo (Miq 1:8, emparejado con chacales), soledad (Job 30:29) y devastación entre ruinas (Isa 13:21; 34:13; Jer 50:39). Aparece como ritualmente impura en Lev 11:16 y Deut 14:15. La traducción es uniforme en todas las lenguas principales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102924, 'spa', 'cansarse / agotarse', 'Cansarse, agotarse, desfallecer por esfuerzo o privación. El verbo Qal y sus formas derivadas abarcan el cansancio físico y espiritual: el herrero que desfallece de sed al forjar un ídolo (Is 44:12), jóvenes que tropiezan exhaustos (Is 40:30), naciones que ''se fatigan'' en vano (Hab 2:13; Jer 51:58, 64), y el asno salvaje que jadea de calor hasta quedar rendido (Jer 2:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102928, 'spa', 'volar / ser hecho volar (Hofal)', 'Volar, ser hecho volar velozmente (participio Hofal). Daniel 9:21 describe al ángel Gabriel como מֻעָף בִּיעָף, ''hecho volar en vuelo veloz'' o ''fatigado con fatiga'' (la frase es deliberadamente ambigua). La mayoría de las traducciones modernas y la evidencia multilingüe favorecen ''volando velozmente'': el español da ''volando'' y el inglés ''caused to fly''. Podría representar una raíz distinta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102932, 'spa', 'Exhausto o agotado', 'Aquellos en estado de agotamiento o desfallecimiento, ya sea físico (por falta de alimento o bebida) o espiritual (por las cargas de la vida). El Siervo isaiano sabe cómo hablar a tales personas, mientras que Yahvé mismo los fortalece. Los contextos presentan consistentemente al cansado no como perezoso, sino como alguien genuinamente extenuado, haciéndolo objeto apropiado de compasión e intervención divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102934, 'spa', 'Consultar juntos (Nifal/Hitpael)', 'Consultar juntos (Nifal/Hitpael): Nifal/Hitpael recíproco: consultar juntos, tomar consejo mutuamente, deliberar con otros, con 23 ocurrencias concentradas en los libros narrativos. Roboam ''consultó'' con los ancianos y luego con los jóvenes (1 R 12:6-9); Nehemías ''consultó consigo mismo'' antes de actuar (Neh 5:7). El árabe tashawara (''consultar mutuamente'') y el coreano 의논하다 (''discutir/deliberar'') captan la reciprocidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102935, 'spa', 'Determinar, planificar (Qal)', 'Determinar, planificar (Qal): Qal con énfasis en determinar, planificar o decretar un curso de acción, con 14 ocurrencias, a menudo con Dios como sujeto expresando decreto soberano. En Is 14:24-27 Dios declara ''como lo he determinado, así se mantendrá'' y ''¿quién lo anulará?'' En Is 19:12 la pregunta retórica es ''¿qué ha determinado el SEÑOR de los ejércitos contra Egipto?'' El árabe qasada/qada (''pretender/decretar'') y el coreano 계획하다 (''planificar'') confirman el campo semántico deliberativo-estratégico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102936, 'spa', 'Aconsejar, dar consejo (Qal)', 'Aconsejar, dar consejo (Qal): Qal activo: aconsejar, dar consejo a otro, con 18 ocurrencias que enfatizan el acto directo de aconsejar. Jetro dice a Moisés ''yo te aconsejaré'' (Éx 18:19); Balaam dice a Balac ''te aconsejaré'' (Nm 24:14); el consejo de Ahitofel a Absalón era legendario (2 S 16:23; 17:7-11). El español aconsejar, el alemán raten y el coreano 조언하다 convergen en el acto interpersonal de dar consejo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102938, 'spa', 'Consejero (participio Qal)', 'Consejero (participio Qal): participio activo Qal sustantivado: un consejero, asesor, con 23 ocurrencias que funcionan como título o designación de oficio. Ahitofel es el יוֹעֵץ de David (2 S 15:12); el cronista enumera ''consejeros'' entre los funcionarios reales (1 Cr 27:32-33); Isaías incluye יוֹעֵץ en su catálogo de líderes removidos de Jerusalén (Is 3:3). El árabe mushir (''consejero'') y el suajili mshauri reflejan el mismo patrón de sustantivo de agente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102955, 'spa', 'Lo determinado (participio pasivo Qal)', 'Lo determinado (participio pasivo Qal): participio pasivo Qal: lo determinado o decretado, con 1 ocurrencia en Is 14:26, ''este es el plan que está determinado sobre toda la tierra''. El participio pasivo הַיְּעוּצָה trata el plan divino como una entidad cumplida y caracterizada: el decreto ya determinado. El español el aconsejado y el alemán das Beschlossene sustantivan el resultado de la planificación de Dios. Esta forma completa el arco semántico del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102984, 'spa', 'Jacob (patriarca/nación)', 'Nombre propio masculino del patriarca, hijo de Isaac y Rebeca (Gn 25:26), cuyas 349 apariciones abarcan su biografía personal y su papel como ancestro epónimo de las doce tribus. El nombre se etimologiza popularmente a partir de ''aqev (''talón'', Gn 25:26) y ''aqav (''suplantar'', Gn 27:36). Tras su teofanía en Peniel recibió el nombre Israel (Gn 32:28), y desde entonces ''Jacob'' e ''Israel'' alternan en la poesía profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (102999, 'spa', 'Bosque, arboleda, espesura', 'Bosque, arboleda, espesura: un bosque, arboleda o espesura (55 veces), referido a terreno boscoso natural. Dt 19:5 describe a un hombre que va con su prójimo al יַעַר a cortar árboles, y 2 S 18:6-8 narra cómo el bosque de Efraín consumió más soldados que la espada en la rebelión de Absalón. Jer 10:3 habla de cortar madera del bosque para hacer un ídolo. La evidencia multilingue (''forest/bosque/foret/Wald'') es unánime al identificar vegetación arbórea densa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103008, 'spa', 'Yaar (nombre de lugar)', 'Yaar (nombre de lugar): un nombre propio ''Yaar'' (1 vez) en Sal 132:6, dentro del recuerdo litúrgico del hallazgo del Arca: ''oímos de ella en Efrata, la encontramos en los campos de Yaar''. Esto probablemente se refiere a Quiriat-jearim (''ciudad de los bosques''), donde el Arca reposó por veinte años (1 S 7:1-2). La glosa alemana ''Yaar'' preserva la lectura como nombre propio, mientras que el español ''bosque'' y el francés foret lo asimilan al sustantivo común.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103015, 'spa', 'Panal silvestre', 'La estructura del panal que contiene miel silvestre, hallada en bosques o zonas rocosas. El encuentro de Jonatán con el panal del bosque (donde ''las abejas se habían ido'', según la LXX) presenta la miel como sustento providencial en contextos de desierto. En Cantares, comer el panal con la miel intensifica la imagen de dulzura y plenitud. El término aparece en escenarios donde la miel silvestre representa un don inesperado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103024, 'spa', 'Ser hermoso, ser bello', 'Ser hermoso, ser bello en apariencia (Qal). Describe una belleza intrínseca o concedida por Dios. Cantares 4:10 exclama ''¡cuán hermosas son tus caricias!'' y 7:6 declara ''¡cuán hermosa eres, oh amada!'' Ezequiel 16:13 narra cómo Jerusalén llegó a ser extraordinariamente bella bajo el adorno de Dios, mientras que Ezequiel 31:7 describe la grandeza de Egipto bajo la figura de un árbol magnífico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103026, 'spa', 'Embellecer, adornar', 'Embellecer, adornar o hacer hermoso, abarcando las conjugaciones Piel (causativa) y Hitpael (reflexiva). En Jeremías 10:4 el Piel yeyappehu describe a artesanos embelleciendo un ídolo con recubrimientos de plata y oro. En Jeremías 4:30 el Hitpael tittyappi retrata a Judá engalanándose, pintándose los ojos y vistiéndose de carmesí para atraer amantes que finalmente la rechazarán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103031, 'spa', 'hermoso, bello, apuesto', 'hermoso, bello, apuesto');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103038, 'spa', 'apropiado, conveniente', 'apropiado, conveniente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103046, 'spa', 'Puerto mediterráneo', 'Jope aparece como destino costero de la madera de cedro transportada desde el Líbano para la construcción del segundo templo (2 Cr 2:16; Esd 3:7), asignada al territorio tribal de Dan (Jos 19:46) y, de forma memorable, como el puerto donde Jonás se embarcó rumbo a Tarsis al huir del mandato divino de predicar en Nínive (Jon 1:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103049, 'spa', 'Belleza, esplendor', 'Belleza, esplendor: belleza física o esplendor estético atribuido a personas (la hermosura de una novia en Sal 45:11; la forma ideal de un rey en Is 33:17), ciudades (Sión como ''perfección de belleza'' en Sal 50:2; la gloria marítima de Tiro en Ez 27:3–4) y la abundancia de la tierra (Zac 9:17). El término aparece frecuentemente en contextos donde la belleza se convierte en fuente de orgullo y caída (Ez 28:17; Pr 31:30), lo que le confiere un matiz de advertencia moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103063, 'spa', 'Nombre propio', 'Nombre propio aplicado tanto a personas como a una localidad. El rey cananeo Jafía de Laquis se alió con otros cuatro reyes contra Josué en Gabaón (Jos 10:3). El hijo de David llamado Jafía nació durante el período jerosolimitano (2 S 5:15; 1 Cr 3:7; 14:6). La ciudad de Jafía en la frontera de Zabulón (Jos 19:12) podría ser la moderna Yafa, cerca de Nazaret.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103064, 'spa', 'Nombre propio aserita', 'Nombre personal aserita preservado en el marco genealógico de Crónicas. Su triple aparición en dos versículos establece a Yaflet como un eslabón significativo en el linaje de Aser, aunque no conocemos nada de su historia individual. Las variantes textuales (Yaflet/Yaflat) y las diversas formas griegas demuestran los desafíos de preservar y transmitir nombres propios a través de múltiples manos escribales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103066, 'spa', 'Jefuné (nombre propio)', 'Jefuné (nombre propio): el nombre propio Yefuné, que identifica principalmente al padre de Caleb el quenizeo, quien junto con Josué fue el único que sobrevivió a la generación del desierto gracias a su fidelidad incondicional (Nm 14:6, 30; 26:65; 32:12; Dt 1:36). También lo lleva un personaje menor de la tribu de Aser (1 Cr 7:38). La etimología del nombre es incierta, pero podría derivar de la raíz פָּנָה (''volverse''), quizá significando ''él fue vuelto hacia Dios''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103069, 'spa', 'Resplandecer, hacer brillar', 'Resplandecer, emitir rayos, hacer irradiar; exclusivamente en Hiphil, describiendo la irrupción activa de la luz. Principalmente teofánico: Dios resplandece desde Parán (Deut 33:2), desde Sion (Sal 50:2), y se le invoca a manifestarse en resplandor (Sal 80:2; 94:1). En Job describe tanto la luz deseada (3:4) como el brillo aterrador de las nubes tormentosas (37:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103077, 'spa', 'Jafet (nombre propio)', 'Tercer hijo de Noé y hermano de Sem y Cam, antepasado de pueblos asociados con Asia Menor, las costas mediterráneas y las regiones del norte. Aparece en contextos de orden de nacimiento (Gn 5:32; 6:10; 7:13; 9:18; 10:1; 1 Cr 1:4) y en la Tabla de las Naciones como padre de siete hijos (Gn 10:2-5; 1 Cr 1:5). Recibió la bendición de Noé de ''ensanchamiento'' mediante un juego de palabras con su nombre (Gn 9:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103081, 'spa', 'Jefté el galaadita — juez de Israel cuya historia domina Jueces 11-12', 'Jefté el galaadita — juez de Israel cuya historia domina Jueces 11-12. Hijo de Galaad con una prostituta, fue expulsado por sus medio hermanos, se convirtió en líder de forajidos y luego fue llamado a combatir a los amonitas. Su voto precipitado y su cumplimiento (Jue 11:30-40) lo convierten en una de las figuras más complejas de la Escritura. Samuel lo recuerda entre los libertadores designados por Dios (1 Sam 12:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103084, 'spa', 'Iftá — una ciudad en la Sefela (tierras bajas) de Judá incluida en la asignación', 'Iftá — una ciudad en la Sefela (tierras bajas) de Judá incluida en la asignación tribal de Josué (Jos 15:43), agrupada con Asná y Nezib. La marca gramatical de femenino singular (N-proper-fs) distingue este topónimo del nombre personal masculino. Se trata de un hápax para el sentido geográfico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103087, 'spa', 'Qal: salir, partir', 'Qal intransitivo: salir, partir, emerger — el sentido base abrumadoramente dominante con 891 ocurrencias. Movimiento físico hacia afuera desde un espacio cerrado o definido: salir de una ciudad (Gn 14:8), abandonar una tienda (Gn 31:33), emerger del arca (Gn 8:7), escapar de un lugar condenado (Gn 19:14). El alcance se extiende naturalmente al agua que ''sale'' de una roca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103097, 'spa', 'Hifil: sacar personas', 'Hifil causativo con personas: sacar, hacer salir, liberar — 172 ocurrencias, dominadas por la fórmula del Éxodo ''que os sacó de la tierra de Egipto'' (Éx 6:13, 6:27; Dt 5:6). El causativo añade un agente poderoso: Dios, Moisés o un líder humano hace que personas salgan de la esclavitud, la prisión o el peligro. El árabe أَخْرَجَ refleja la morfología hebrea con exactitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103203, 'spa', 'Hifil: producir, proferir', 'Hifil causativo con objetos no personales: producir, hacer brotar, proferir — 11 ocurrencias donde lo que se ''saca'' no es una persona sino una cosa, declaración o producto natural. La vara de Aarón ''produjo'' brotes y almendras (Nm 17:8); los espías ''sacaron'' un informe desfavorable (Nm 14:37); una esposa debe ser ''despedida'' en procesos de divorcio (Esd 10:3, 19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103245, 'spa', 'Hofal: ser sacado', 'Hofal pasivo: ser sacado — una sola ocurrencia en Ezequiel 38:8 donde Israel es descrito como un pueblo ''sacado de entre la espada,'' usando el pasivo del Hifil. El agente está implícito (Dios) y el foco recae sobre la nación como receptora de la liberación, no sobre el libertador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103264, 'spa', 'salida del sol, amanecer', 'Qal con sujeto celeste/natural: la salida del sol — ocurrencia especializada en Génesis 19:23 donde ''el sol había salido sobre la tierra'' cuando Lot entró en Zoar. Aunque estructuralmente idéntico al sentido 1 (movimiento intransitivo hacia afuera), el sujeto es un cuerpo celeste y el significado es ''salir, alzarse.'' El alemán war aufgegangen (''había salido'') y el coreano 떠올랐다 (''se alzó'') seleccionan vocabulario de amanecer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103317, 'spa', 'Pararse, tomar posición', 'Pararse, tomar posición: el sentido físico central: pararse o tomar posición en un lugar específico, a menudo como acción narrativa de ubicación. Miriam se aposta a la orilla del río (Éx 2:4), el ángel del SEÑOR se posiciona en el camino para bloquear a Balaam (Nm 22:22) y Yahvé desciende y se para con Moisés en el Sinaí (Éx 34:5). El español pararse y el alemán sich-stellen captan la cualidad deliberada y reflexiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103318, 'spa', 'Presentarse ante autoridad', 'Presentarse ante autoridad: presentación formal ante un superior, asamblea o Dios, el sentido protocolar. Israel se presenta ante Yahvé al pie del Sinaí (Éx 19:17); las tribus se reúnen ante Dios en Siquem (Jos 24:1); el campeón filisteo ''se presenta'' durante cuarenta días (1 S 17:16). El francés se presenter y el español presentarse seleccionan vocabulario de aparición ceremonial distinto del simple estar de pie.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103320, 'spa', 'Apostarse deliberadamente', 'Apostarse deliberadamente: posicionarse de manera deliberada con un propósito táctico o de vigilancia. Dios ordena a Moisés: ''Preséntate ante Faraón por la mañana'' (Éx 8:20; 9:13), enmarcando la confrontación como planificada e intencional. Habacuc se aposta en la atalaya para esperar la respuesta de Dios (Hab 2:1), y Balaam dirige a Balac a ''pararse aquí'' mientras él va a buscar un oráculo (Nm 23:3, 15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103321, 'spa', 'Tomar posición juntos', 'Tomar posición juntos: asamblea colectiva para acción comunitaria o ceremonial, la dimensión corporativa. Samuel convoca a Israel: ''Presentaos ante el SEÑOR por vuestras tribus'' (1 S 10:19); los reúne para litigación pactual: ''Estad aquí, para que yo argumente con vosotros ante el SEÑOR'' (1 S 12:7). El francés presentez-vous y el español presentaos usan formas reflexivas plurales que reflejan el Hitpael hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103333, 'spa', 'Mantenerse firme, resistir', 'Mantenerse firme, resistir: mantenerse firme ante la oposición, el sentido de valor y resistencia. El mandato icónico de Moisés en el Mar Rojo: ''Estad firmes y ved la salvación del SEÑOR'' (Éx 14:13) es la instancia paradigmática. En 2 Cr 20:6, Josafat declara que nadie puede ''resistir'' a Dios. Job 41:10 pregunta quién puede ''sostenerse ante'' el Leviatán. El español estar firmes y el cognado árabe waṣaba (''ser constante'') confirman este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103350, 'spa', 'Colocar o poner físicamente', 'Colocar o poner físicamente: el sentido físico básico de colocar, poner o situar un objeto en un lugar específico. Jacob coloca las varas peladas en los abrevaderos ante los rebaños (Gn 30:38), Gedeón pone el vellón en la era (Jue 6:37) y David coloca el arca dentro de la tienda (2 S 6:17). El énfasis recae en el acto deliberado e intencional de posicionar un objeto en su lugar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103351, 'spa', 'Designar o establecer a una persona', 'Designar o establecer a una persona: el sentido de autoridad personal, presentar a alguien formalmente o establecerlo en una posición. José presenta a sus hermanos ante Faraón (Gn 47:2) y Judá se compromete a ''poner'' a Benjamín de nuevo ante su padre (Gn 43:9). En Job 17:6 el sufriente lamenta que Dios lo ha puesto como proverbio entre las gentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103355, 'spa', 'Apostar o dejar en un lugar', 'Apostar o dejar en un lugar: el sentido estativo-resultativo de apostar, dejar o mantener en un lugar fijo, enfatizando el estado permanente más que el acto inicial. Oseas amenaza con ''ponerla'' como un desierto (Os 2:3), despojándola de todo adorno. Moisés pide a Faraón que deje quedarse a los pequeños (Éx 10:24), y Jacob ofrece dejar apostada parte de su gente (Gn 33:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103366, 'spa', 'Aceite de oliva recién prensado, que aparece de manera formulaica en la tríada c', 'Aceite de oliva recién prensado, que aparece de manera formulaica en la tríada con el grano y el vino nuevo como bendiciones del pacto (Dt 7:13; 11:14; Os 2:8; Jl 2:19). Sujeto al diezmo (Dt 12:17; 14:23) y a las primicias sacerdotales (Nm 18:12; Dt 18:4; Neh 10:37). El hebreo distingue yitshār de shemen, aunque el español emplea el término general ''aceite'' para ambos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103372, 'spa', 'Yitshar (Izhar)', 'Nombre propio masculino que designa a un ancestro levítico, segundo hijo de Coat y hermano de Amram, Hebrón y Uziel (Éx 6:18). Su línea genealógica se traza a través de Coré (Núm 16:1), lo que lo convierte en progenitor de los coreítas, los cantores y porteros del templo celebrados en los títulos de varios salmos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103375, 'spa', 'Clan levítico', 'Los izharitas aparecen en las listas censales y los turnos de servicio levítico como uno de los clanes coatitas (Nm 3:27), con líderes específicos nombrados en la organización del templo del Cronista (1 Cr 24:22; 26:23, 29). El hebreo emplea la forma gentilicia con artículo como sustantivo colectivo, literalmente ''los de Izhar,'' designando a toda la línea familiar dedicada al servicio sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103376, 'spa', 'Cámara lateral, anexo', 'Término arquitectónico para las cámaras laterales o anexos construidos alrededor de los muros exteriores del templo de Salomón (1 R 6:5, 6, 10). Eran habitaciones de varios pisos cuya anchura aumentaba en cada nivel porque el muro del templo se estrechaba mediante repisas. La lectura Ketiv יָצוּעַ conecta esta estructura con la idea raíz de extenderse o disponerse a lo largo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103377, 'spa', 'Lecho, diván', 'Lecho o diván para dormir o reclinarse, empleado en contextos poéticos y emocionalmente intensos. Casi siempre aparece con sufijo posesivo de primera persona (''mi lecho''), confiriéndole un tono íntimo. En Génesis 49:4 Jacob reprende a Rubén por subir al ''lecho de tu padre'', eufemismo por la violación de su concubina Bilha. Salmo 63:7 evoca la meditación nocturna ''sobre mi cama''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103382, 'spa', 'Cámara lateral del templo', 'Las dependencias laterales adosadas a los muros exteriores del templo de Salomón, que formaban espacios auxiliares alrededor del santuario principal. יָצִיעַ aparece exclusivamente en estos versículos sobre la construcción del templo. Estas cámaras representaban un espacio sagrado funcional: ni tan santo como el lugar santísimo, ni meramente secular, sino aposentos prácticos consagrados al servicio del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103383, 'spa', 'Isaac (nombre propio)', 'Nombre propio masculino Yitsjaq (Isaac), que designa al hijo de Abraham y Sara, segundo de los tres patriarcas. La etimología del nombre (''él ríe'') se vincula tanto a la risa incrédula de Sara (Gn 18:12) como a su risa gozosa (Gn 21:6). Las 108 apariciones se refieren al mismo individuo, en fórmulas de alianza (Lv 26:42), genealogías (1 Cr 1:28) y poéticamente como metonimia de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103394, 'spa', 'Cierto, seguro', 'Cierto, seguro — expresa fiabilidad firme o un hecho establecido. Se usa adverbialmente con מִן como ''de cierto'' (Dn 2:8) y predicativamente para la certeza de una revelación divina (Dn 2:45). El empleo exclamativo en Dn 3:24 funciona como ''¡sin duda!'' cuando Nabucodonosor reacciona ante la cuarta figura en el horno. La forma femenina sustantivada en Dn 7:16 designa ''la verdad'' que Daniel busca para comprender su visión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103395, 'spa', 'Extender o tender', 'El verbo aparece en las conjugaciones Hifil y Hofal describiendo la acción de extender o tender. El salmista pregunta retóricamente: ''Si en el Seol hiciera mi cama, allí tú estás'' (Sal 139:8), usando el Hifil para expresar la omnipresencia de Dios. Isaías se burla del falso ayuno: ¿acaso ''extender'' cilicio y ceniza equivale a preparar un lecho apropiado (Is 58:5)? El Hofal pasivo aparece cuando se ''extienden'' cilicio y ceniza en señal de duelo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103396, 'spa', 'Fundir metal', 'Fundir metal: fundir o moldear metal vertiendo material fundido en un molde, produciendo columnas, basas, espejos y vasos sagrados. Las instrucciones del tabernáculo especifican fundir anillos de oro (Éx 25:12; 37:3, 13) y basas de bronce (Éx 26:37; 36:36); el artesano de Salomón, Hiram, fundió las grandes obras de bronce en el valle del Jordán (1 R 7:46). El español pasa decisivamente de ''verter'' a ''fundir'', marcando la especialización metalúrgica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103397, 'spa', 'Verter, derramar líquido', 'Verter, derramar líquido: verter un líquido —aceite, agua, sangre o caldo— ya sea en unción ritual, ofrenda sacrificial o servicio cotidiano. Jacob vertió aceite sobre la piedra en Betel (Gn 28:18, 35:14); Moisés derramó aceite de la unción sobre la cabeza de Aarón (Lv 8:12); Eliseo es identificado como quien ''vertía agua sobre las manos de Elías'' (2 R 3:11). El español vertió y derramaba captan el acto central.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103407, 'spa', 'Firme, duro, sólido', 'Firme, duro, sólido: sentido de participio pasivo que significa ''firme, duro, sólido'': el estado del líquido que fue vertido y ahora se ha solidificado. Job 11:15 promete que si uno aparta la iniquidad, ''serás firme (מוּצָק) y sin temor''. El español firme capta la metáfora: lo que antes era fundido ahora es inquebrantablemente sólido. Esta única ocurrencia tiende un puente entre los sentidos de verter líquido y fundir metal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103423, 'spa', 'Depositar, colocar', 'Depositar, colocar: uso extendido que significa depositar o colocar algo en un lugar, generalizando del vertido controlado de líquido a la colocación deliberada de un objeto pesado. En 2 S 15:24, los levitas depositan (וַיַּצִּקוּ) el arca de Dios. El español pusieron (''colocaron'') y el alemán setzte hinab (''depositó'') lo confirman. El vínculo semántico con el acto de verter sobrevive en la cualidad cuidadosa y deliberada del gesto.');